// Package push sends Web Push (VAPID) notifications and manages browser
// push subscriptions. Keys come from VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY
// (base64url, generated by `webpush generate_keys`); without them the
// sender is a no-op and subscriptions are not advertised.
package push

import (
	"context"
	"crypto/ecdh"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"errors"
	"log"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/SherClockHolmes/webpush-go"
)

type Subscription struct {
	Endpoint string
	P256DH   string
	Auth     string
}

var (
	keysOnce    sync.Once
	vapidPublic string
	vapidPriv   string
	contact     string
)

func loadKeys() {
	vapidPublic = strings.TrimSpace(getenv("VAPID_PUBLIC_KEY"))
	vapidPriv = strings.TrimSpace(getenv("VAPID_PRIVATE_KEY"))
	contact = strings.TrimSpace(getenv("VAPID_CONTACT"))
	if contact == "" {
		contact = "mailto:admin@velm.dev"
	}
}

func getenv(name string) string {
	return strings.TrimSpace(os.Getenv(name))
}

// Enabled reports whether web push is configured on this instance.
func Enabled() bool {
	keysOnce.Do(loadKeys)
	return vapidPublic != "" && vapidPriv != ""
}

// PublicKey returns the base64url VAPID public key for client subscription.
func PublicKey() string {
	keysOnce.Do(loadKeys)
	return vapidPublic
}

// GenerateVapidKeys creates a new base64url key pair (used by tooling/tests).
func GenerateVapidKeys() (publicKey, privateKey string, err error) {
	curve := ecdh.P256()
	priv, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return "", "", err
	}
	privBytes := priv.Bytes()
	if len(privBytes) != 32 {
		return "", "", errors.New("unexpected private key length")
	}
	return base64.RawURLEncoding.EncodeToString(priv.PublicKey().Bytes()),
		base64.RawURLEncoding.EncodeToString(privBytes), nil
}

type SendResult struct {
	Sent    int
	Removed int
	Failed  int
	Stale   []string // endpoints to delete (404/410 from the push service)
}

// Send delivers one payload to all subscriptions. Stale endpoints
// (gone/failing permanently) are reported so the caller can delete them.
// Failures are logged, never returned to the notification path: in-app
// notifications must not fail because push is misconfigured.
func Send(ctx context.Context, subs []Subscription, title, body, href string) SendResult {
	keysOnce.Do(loadKeys)
	res := SendResult{}
	if !Enabled() || len(subs) == 0 {
		return res
	}
	payload, err := marshalPayload(title, body, href)
	if err != nil {
		log.Printf("push: payload marshal failed: %v", err)
		return res
	}
	for _, sub := range subs {
		resp, err := webpush.SendNotification([]byte(payload), &webpush.Subscription{
			Endpoint: sub.Endpoint,
			Keys: webpush.Keys{
				P256dh: sub.P256DH,
				Auth:   sub.Auth,
			},
		}, &webpush.Options{
			Subscriber:      contact,
			VAPIDPublicKey:  vapidPublic,
			VAPIDPrivateKey: vapidPriv,
			TTL:             int((24 * time.Hour).Seconds()),
		})
		if err != nil {
			if resp != nil && (resp.StatusCode == 404 || resp.StatusCode == 410) {
				res.Stale = append(res.Stale, sub.Endpoint)
				res.Removed++
			} else {
				res.Failed++
			}
			log.Printf("push: send to %s… failed: %v", trimEndpoint(sub.Endpoint), err)
			continue
		}
		if resp != nil && resp.Body != nil {
			resp.Body.Close()
		}
		res.Sent++
	}
	return res
}

func trimEndpoint(endpoint string) string {
	if len(endpoint) > 60 {
		return endpoint[:60]
	}
	return endpoint
}

func marshalPayload(title, body, href string) (string, error) {
	type payload struct {
		Title string `json:"title"`
		Body  string `json:"body"`
		Href  string `json:"href,omitempty"`
	}
	truncate := func(s string, n int) string {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	b, err := json.Marshal(payload{
		Title: truncate(title, maxPushTitle),
		Body:  truncate(body, maxPushBody),
		Href:  truncate(href, maxPushHref),
	})
	return string(b), err
}

const (
	maxPushTitle = 180
	maxPushBody  = 500
	maxPushHref  = 2048
)
